\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the projection of $\vec{u} = \langle 3, 4, -1 \rangle$ onto $\vec{v} = \langle 2, 1, 2 \rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Compute $\vec{u} \cdot \vec{v}$

\[
\vec{u} \cdot \vec{v} = (3)(2) + (4)(1) + (-1)(2) = 6 + 4 - 2 = 8
\]

\textbf{Step 2:} Compute $|\vec{v}|^2$

\[
|\vec{v}|^2 = 2^2 + 1^2 + 2^2 = 4 + 1 + 4 = 9
\]

\textbf{Step 3:} Apply projection formula

\begin{align*}
\text{proj}_{\vec{v}}\vec{u} &= \frac{\vec{u} \cdot \vec{v}}{|\vec{v}|^2}\vec{v} \\
&= \frac{8}{9}\langle 2, 1, 2 \rangle \\
&= \left\langle \frac{16}{9}, \frac{8}{9}, \frac{16}{9} \right\rangle
\end{align*}

\textbf{Answer:} \boxed{\text{proj}_{\vec{v}}\vec{u} = \left\langle \frac{16}{9}, \frac{8}{9}, \frac{16}{9} \right\rangle}

\textbf{Scalar component:}
\[
\text{comp}_{\vec{v}}\vec{u} = \frac{\vec{u} \cdot \vec{v}}{|\vec{v}|} = \frac{8}{3}
\]

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 6.3 Summary: Dot Product}}

\textbf{Dot Product Formula:}
\[
\boxed{\vec{u} \cdot \vec{v} = u_1v_1 + u_2v_2 + u_3v_3 = |\vec{u}||\vec{v}|\cos\theta}
\]

\textbf{Angle Between Vectors:}
\[
\boxed{\cos\theta = \frac{\vec{u} \cdot \vec{v}}{|\vec{u}||\vec{v}|}}
\]

\textbf{Orthogonality Test:}
\[
\boxed{\vec{u} \perp \vec{v} \iff \vec{u} \cdot \vec{v} = 0}
\]

\textbf{Projection:}
\[
\boxed{\text{proj}_{\vec{v}}\vec{u} = \left(\frac{\vec{u} \cdot \vec{v}}{|\vec{v}|^2}\right)\vec{v}}
\]

\textbf{Scalar Component:}
\[
\boxed{\text{comp}_{\vec{v}}\vec{u} = \frac{\vec{u} \cdot \vec{v}}{|\vec{v}|}}
\]

\textcolor{red}{\textbf{Exam Alert:}} Orthogonal projections appear \textbf{frequently} in past papers!

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Using $|\vec{v}|$ instead of $|\vec{v}|^2$ in projection formula
    \item Forgetting that dot product produces a scalar, not a vector
    \item Confusing projection (vector) with scalar component (number)
    \item Computing angle outside range $[0, \pi]$
\end{itemize}

\textcolor{green}{\textbf{Key Applications:}}
\begin{itemize}
    \item Finding angles between vectors
    \item Testing for perpendicularity
    \item Computing projections
    \item Calculating work: $W = \vec{F} \cdot \vec{d}$
\end{itemize}

