Given $\vec{u} = \langle u_1, u_2, u_3 \rangle$ and $\vec{v} = \langle v_1, v_2, v_3 \rangle$:

\textbf{Algebraic Definition:}
\[
\boxed{\vec{u} \times \vec{v} = \langle u_2v_3 - u_3v_2, u_3v_1 - u_1v_3, u_1v_2 - u_2v_1 \rangle}
\]

\textbf{Determinant Form:}
\[
\boxed{\vec{u} \times \vec{v} = \begin{vmatrix}
\vec{i} & \vec{j} & \vec{k} \\
u_1 & u_2 & u_3 \\
v_1 & v_2 & v_3
\end{vmatrix}}
\]

Expand along the first row:
\[
\vec{u} \times \vec{v} = \vec{i}\begin{vmatrix} u_2 & u_3 \\ v_2 & v_3 \end{vmatrix} - \vec{j}\begin{vmatrix} u_1 & u_3 \\ v_1 & v_3 \end{vmatrix} + \vec{k}\begin{vmatrix} u_1 & u_2 \\ v_1 & v_2 \end{vmatrix}
\]

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Important:}}

The cross product is defined \textbf{only in $\mathbb{R}^3$}! It does not exist in 2D.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Result:}}

$\vec{u} \times \vec{v}$ is a \textbf{vector} (unlike dot product which is scalar).

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find $\vec{u} \times \vec{v}$ where $\vec{u} = \langle 2, 1, -1 \rangle$ and $\vec{v} = \langle 1, 3, 2 \rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Method 1: Using the formula directly}

\begin{align*}
\vec{u} \times \vec{v} &= \langle u_2v_3 - u_3v_2, u_3v_1 - u_1v_3, u_1v_2 - u_2v_1 \rangle \\
&= \langle (1)(2) - (-1)(3), (-1)(1) - (2)(2), (2)(3) - (1)(1) \rangle \\
&= \langle 2 + 3, -1 - 4, 6 - 1 \rangle \\
&= \langle 5, -5, 5 \rangle
\end{align*}

\textbf{Method 2: Using determinant}

\[
\vec{u} \times \vec{v} = \begin{vmatrix}
\vec{i} & \vec{j} & \vec{k} \\
2 & 1 & -1 \\
1 & 3 & 2
\end{vmatrix}
\]

\begin{align*}
&= \vec{i}\begin{vmatrix} 1 & -1 \\ 3 & 2 \end{vmatrix} - \vec{j}\begin{vmatrix} 2 & -1 \\ 1 & 2 \end{vmatrix} + \vec{k}\begin{vmatrix} 2 & 1 \\ 1 & 3 \end{vmatrix} \\
&= \vec{i}(2 + 3) - \vec{j}(4 + 1) + \vec{k}(6 - 1) \\
&= 5\vec{i} - 5\vec{j} + 5\vec{k} \\
&= \langle 5, -5, 5 \rangle
\end{align*}

\textbf{Answer:} \boxed{\vec{u} \times \vec{v} = \langle 5, -5, 5 \rangle}

\vspace{0.5cm}

Let $\vec{u}$, $\vec{v}$, $\vec{w}$ be vectors and $c$ be a scalar.

\textbf{1. Anti-commutative:}
\[
\vec{u} \times \vec{v} = -(\vec{v} \times \vec{u})
\]

\textbf{2. Distributive:}
\[
\vec{u} \times (\vec{v} + \vec{w}) = \vec{u} \times \vec{v} + \vec{u} \times \vec{w}
\]

\textbf{3. Scalar multiplication:}
\[
(c\vec{u}) \times \vec{v} = c(\vec{u} \times \vec{v}) = \vec{u} \times (c\vec{v})
\]

\textbf{4. Perpendicularity:}
\[
\vec{u} \times \vec{v} \perp \vec{u} \quad \text{and} \quad \vec{u} \times \vec{v} \perp \vec{v}
\]

\textbf{5. Parallel vectors:}
\[
\vec{u} \times \vec{v} = \vec{0} \iff \vec{u} \text{ and } \vec{v} \text{ are parallel (or one is } \vec{0}\text{)}
\]

\textbf{6. Magnitude:}
\[
|\vec{u} \times \vec{v}| = |\vec{u}||\vec{v}|\sin\theta
\]

where $\theta$ is the angle between $\vec{u}$ and $\vec{v}$.

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Warning:}}

The cross product is \textbf{NOT associative}: $\vec{u} \times (\vec{v} \times \vec{w}) \neq (\vec{u} \times \vec{v}) \times \vec{w}$ in general.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Verify that $\vec{u} \times \vec{v}$ from Example 12 is perpendicular to both $\vec{u}$ and $\vec{v}$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

From Example 12: $\vec{u} = \langle 2, 1, -1 \rangle$, $\vec{v} = \langle 1, 3, 2 \rangle$, $\vec{u} \times \vec{v} = \langle 5, -5, 5 \rangle$

\textbf{Check 1:} $(\vec{u} \times \vec{v}) \cdot \vec{u}$

\[
\langle 5, -5, 5 \rangle \cdot \langle 2, 1, -1 \rangle = 10 - 5 - 5 = 0 \quad \textcolor{green}{\checkmark}
\]

\textbf{Check 2:} $(\vec{u} \times \vec{v}) \cdot \vec{v}$

\[
\langle 5, -5, 5 \rangle \cdot \langle 1, 3, 2 \rangle = 5 - 15 + 10 = 0 \quad \textcolor{green}{\checkmark}
\]

\textbf{Conclusion:} $\vec{u} \times \vec{v}$ is perpendicular to both $\vec{u}$ and $\vec{v}$.

\vspace{0.5cm}

\textbf{Direction:} $\vec{u} \times \vec{v}$ is perpendicular to both $\vec{u}$ and $\vec{v}$, following the \textbf{right-hand rule}:
\begin{itemize}
    \item Point fingers of right hand along $\vec{u}$
    \item Curl them toward $\vec{v}$
    \item Thumb points in direction of $\vec{u} \times \vec{v}$
\end{itemize}

\textbf{Magnitude:}
\[
|\vec{u} \times \vec{v}| = |\vec{u}||\vec{v}|\sin\theta
\]

This equals the area of the parallelogram with sides $\vec{u}$ and $\vec{v}$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Area Interpretation:}}
\[
\text{Area of parallelogram} = |\vec{u} \times \vec{v}|
\]
\[
\text{Area of triangle} = \frac{1}{2}|\vec{u} \times \vec{v}|
\]

