\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the area of the parallelogram with vertices at $P(1, 0, 1)$, $Q(2, 3, 1)$, $R(3, 5, 2)$, and $S(2, 2, 2)$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find two adjacent sides as vectors

\begin{align*}
\overrightarrow{PQ} &= \langle 2-1, 3-0, 1-1 \rangle = \langle 1, 3, 0 \rangle \\
\overrightarrow{PS} &= \langle 2-1, 2-0, 2-1 \rangle = \langle 1, 2, 1 \rangle
\end{align*}

\textbf{Step 2:} Compute cross product

\[
\overrightarrow{PQ} \times \overrightarrow{PS} = \begin{vmatrix}
\vec{i} & \vec{j} & \vec{k} \\
1 & 3 & 0 \\
1 & 2 & 1
\end{vmatrix}
\]

\begin{align*}
&= \vec{i}(3 - 0) - \vec{j}(1 - 0) + \vec{k}(2 - 3) \\
&= 3\vec{i} - \vec{j} - \vec{k} \\
&= \langle 3, -1, -1 \rangle
\end{align*}

\textbf{Step 3:} Find magnitude

\[
|\overrightarrow{PQ} \times \overrightarrow{PS}| = \sqrt{3^2 + (-1)^2 + (-1)^2} = \sqrt{9 + 1 + 1} = \sqrt{11}
\]

\textbf{Answer:} \boxed{\text{Area} = \sqrt{11} \text{ square units}}

\vspace{0.5cm}

The \textbf{scalar triple product} of vectors $\vec{u}$, $\vec{v}$, $\vec{w}$ is:
\[
\boxed{\vec{u} \cdot (\vec{v} \times \vec{w})}
\]

This can be computed as a determinant:
\[
\vec{u} \cdot (\vec{v} \times \vec{w}) = \begin{vmatrix}
u_1 & u_2 & u_3 \\
v_1 & v_2 & v_3 \\
w_1 & w_2 & w_3
\end{vmatrix}
\]

\textbf{Geometric Interpretation:}

$|\vec{u} \cdot (\vec{v} \times \vec{w})|$ is the volume of the parallelepiped with edges $\vec{u}$, $\vec{v}$, $\vec{w}$.

\textbf{Properties:}
\begin{itemize}
    \item $\vec{u} \cdot (\vec{v} \times \vec{w}) = \vec{v} \cdot (\vec{w} \times \vec{u}) = \vec{w} \cdot (\vec{u} \times \vec{v})$ (cyclic)
    \item $\vec{u} \cdot (\vec{v} \times \vec{w}) = 0 \iff$ vectors are coplanar
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the volume of the parallelepiped determined by $\vec{u} = \langle 1, 2, 0 \rangle$, $\vec{v} = \langle 0, 1, 3 \rangle$, and $\vec{w} = \langle 2, 0, 1 \rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Compute scalar triple product using determinant

\[
\vec{u} \cdot (\vec{v} \times \vec{w}) = \begin{vmatrix}
1 & 2 & 0 \\
0 & 1 & 3 \\
2 & 0 & 1
\end{vmatrix}
\]

\textbf{Step 2:} Expand (using first row)

\begin{align*}
&= 1\begin{vmatrix} 1 & 3 \\ 0 & 1 \end{vmatrix} - 2\begin{vmatrix} 0 & 3 \\ 2 & 1 \end{vmatrix} + 0\begin{vmatrix} 0 & 1 \\ 2 & 0 \end{vmatrix} \\
&= 1(1 - 0) - 2(0 - 6) + 0 \\
&= 1 + 12 \\
&= 13
\end{align*}

\textbf{Step 3:} Volume is absolute value

\[
V = |\vec{u} \cdot (\vec{v} \times \vec{w})| = |13| = 13
\]

\textbf{Answer:} \boxed{V = 13 \text{ cubic units}}

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 6.4 Summary: Cross Product}}

\textbf{Cross Product Formula:}
\[
\boxed{\vec{u} \times \vec{v} = \begin{vmatrix}
\vec{i} & \vec{j} & \vec{k} \\
u_1 & u_2 & u_3 \\
v_1 & v_2 & v_3
\end{vmatrix}}
\]

\textbf{Key Properties:}
\begin{itemize}
    \item $\vec{u} \times \vec{v} = -\vec{v} \times \vec{u}$ (anti-commutative)
    \item $\vec{u} \times \vec{v} \perp \vec{u}$ and $\vec{u} \times \vec{v} \perp \vec{v}$
    \item $|\vec{u} \times \vec{v}| = |\vec{u}||\vec{v}|\sin\theta$
    \item $\vec{u} \times \vec{v} = \vec{0} \iff \vec{u} \parallel \vec{v}$
\end{itemize}

\textbf{Applications:}
\begin{align*}
\text{Area of parallelogram:} \quad & |\vec{u} \times \vec{v}| \\
\text{Area of triangle:} \quad & \frac{1}{2}|\vec{u} \times \vec{v}| \\
\text{Volume of parallelepiped:} \quad & |\vec{u} \cdot (\vec{v} \times \vec{w})|
\end{align*}

\textbf{Standard Cross Products:}
\begin{align*}
\vec{i} \times \vec{j} &= \vec{k}, \quad \vec{j} \times \vec{k} = \vec{i}, \quad \vec{k} \times \vec{i} = \vec{j} \\
\vec{j} \times \vec{i} &= -\vec{k}, \quad \vec{k} \times \vec{j} = -\vec{i}, \quad \vec{i} \times \vec{k} = -\vec{j}
\end{align*}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Forgetting the minus sign on the $\vec{j}$ component in determinant expansion
    \item Thinking cross product is commutative (it's anti-commutative!)
    \item Trying to use cross product in 2D (only defined in 3D)
    \item Confusing $\vec{u} \times \vec{v}$ with $\vec{u} \cdot \vec{v}$ (vector vs. scalar)
\end{itemize}

\textcolor{green}{\textbf{Quick Check:}}
\begin{itemize}
    \item $\vec{i} \times \vec{j} = \vec{k}$ (right-hand rule)
    \item Cross product result is perpendicular to both original vectors
    \item Magnitude equals area of parallelogram
\end{itemize}

\newpage

A \textbf{vector function} (or \textbf{vector-valued function}) is a function that assigns a vector to each value of a parameter $t$ in its domain.

\textbf{In 2D:}
\[
\vec{r}(t) = \langle f(t), g(t) \rangle = f(t)\vec{i} + g(t)\vec{j}
\]

\textbf{In 3D:}
\[
\boxed{\vec{r}(t) = \langle f(t), g(t), h(t) \rangle = f(t)\vec{i} + g(t)\vec{j} + h(t)\vec{k}}
\]

where $f$, $g$, and $h$ are called the \textbf{component functions}.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Geometric Interpretation:}}

As $t$ varies, the tip of the vector $\vec{r}(t)$ traces out a curve $C$ in space. The curve is called the \textbf{graph} of $\vec{r}(t)$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Parametric Equations:}}

The component form gives the parametric equations:
\[
x = f(t), \quad y = g(t), \quad z = h(t)
\]

