\textcolor{primaryblue}{\textbf{Problem:}} Describe the curve traced by $\vec{r}(t) = \langle \cos t, \sin t, t \rangle$ for $t \geq 0$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Identify parametric equations

\begin{align*}
x &= \cos t \\
y &= \sin t \\
z &= t
\end{align*}

\textbf{Step 2:} Analyze the $xy$-projection

From $x^2 + y^2 = \cos^2 t + \sin^2 t = 1$, the projection onto the $xy$-plane is a circle of radius 1.

\textbf{Step 3:} Include the $z$-component

As $t$ increases from 0 to $\infty$:
\begin{itemize}
    \item $(x, y)$ traces around the unit circle
    \item $z = t$ increases linearly
\end{itemize}

\textbf{Answer:} The curve is a \textbf{circular helix} (spiral) that winds around the $z$-axis.

\textbf{Key points:}
\begin{itemize}
    \item At $t = 0$: $(1, 0, 0)$
    \item At $t = \pi/2$: $(0, 1, \pi/2)$
    \item At $t = \pi$: $(-1, 0, \pi)$
    \item At $t = 2\pi$: $(1, 0, 2\pi)$
\end{itemize}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Visualization:}} The helix rises while circling the $z$-axis with constant radius 1.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find a vector function that represents the curve of intersection of:
\begin{itemize}
    \item Cylinder: $x^2 + y^2 = 4$
    \item Plane: $z = x + y$
\end{itemize}

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Parametrize the cylinder

Use $x = 2\cos t$ and $y = 2\sin t$ (circle of radius 2).

\textbf{Step 2:} Find $z$ from the plane equation

\begin{align*}
z &= x + y \\
&= 2\cos t + 2\sin t \\
&= 2(\cos t + \sin t)
\end{align*}

\textbf{Step 3:} Write vector function

\[
\vec{r}(t) = \langle 2\cos t, 2\sin t, 2(\cos t + \sin t) \rangle
\]

for $0 \leq t \leq 2\pi$.

\textbf{Answer:} \boxed{\vec{r}(t) = \langle 2\cos t, 2\sin t, 2\cos t + 2\sin t \rangle}

\vspace{0.5cm}

\textbf{Limit of a Vector Function:}
\[
\boxed{\lim_{t \to a} \vec{r}(t) = \left\langle \lim_{t \to a} f(t), \lim_{t \to a} g(t), \lim_{t \to a} h(t) \right\rangle}
\]

provided each component limit exists.

\textbf{Continuity:}

$\vec{r}(t)$ is \textbf{continuous} at $t = a$ if:
\[
\lim_{t \to a} \vec{r}(t) = \vec{r}(a)
\]

This means each component function is continuous at $a$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Domain:}}

The domain of $\vec{r}(t)$ is the intersection of the domains of its component functions.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find $\displaystyle \lim_{t \to 0} \vec{r}(t)$ where $\vec{r}(t) = \left\langle \frac{\sin t}{t}, t^2 - 1, e^t \right\rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

Compute the limit of each component:

\textbf{Component 1:}
\[
\lim_{t \to 0} \frac{\sin t}{t} = 1
\]

\textbf{Component 2:}
\[
\lim_{t \to 0} (t^2 - 1) = 0 - 1 = -1
\]

\textbf{Component 3:}
\[
\lim_{t \to 0} e^t = e^0 = 1
\]

\textbf{Answer:} \boxed{\lim_{t \to 0} \vec{r}(t) = \langle 1, -1, 1 \rangle}

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 6.5 Summary: Vector Functions}}

\textbf{Vector Function:}
\[
\boxed{\vec{r}(t) = \langle f(t), g(t), h(t) \rangle}
\]

\textbf{Parametric Equations:}
\[
x = f(t), \quad y = g(t), \quad z = h(t)
\]

\textbf{Limit:}
\[
\lim_{t \to a} \vec{r}(t) = \left\langle \lim_{t \to a} f(t), \lim_{t \to a} g(t), \lim_{t \to a} h(t) \right\rangle
\]

\textbf{Common Curves:}
\begin{itemize}
    \item Line: $\vec{r}(t) = \vec{r}_0 + t\vec{v}$
    \item Circle: $\vec{r}(t) = \langle a\cos t, a\sin t, 0 \rangle$
    \item Helix: $\vec{r}(t) = \langle a\cos t, a\sin t, bt \rangle$
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Confusing vector function with scalar function
    \item Not checking domain restrictions for each component
    \item Forgetting that limits are computed component-wise
\end{itemize}

\textcolor{green}{\textbf{Key Insight:}} Vector functions parametrize curves in space, giving position as a function of time or parameter.

\newpage

The \textbf{derivative} of $\vec{r}(t) = \langle f(t), g(t), h(t) \rangle$ is:
\[
\boxed{\vec{r}'(t) = \lim_{\Delta t \to 0} \frac{\vec{r}(t + \Delta t) - \vec{r}(t)}{\Delta t}}
\]

\textbf{Component-wise:}
\[
\boxed{\vec{r}'(t) = \langle f'(t), g'(t), h'(t) \rangle}
\]

\textbf{Alternative Notations:}
\[
\vec{r}'(t) = \frac{d\vec{r}}{dt} = \dot{\vec{r}}(t)
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Geometric Interpretation:}}

$\vec{r}'(t)$ is the \textbf{tangent vector} to the curve at the point $\vec{r}(t)$. It points in the direction of motion along the curve.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Physical Interpretation:}}

If $\vec{r}(t)$ represents position at time $t$, then:
\begin{itemize}
    \item $\vec{r}'(t) = \vec{v}(t)$ is the velocity vector
    \item $|\vec{r}'(t)|$ is the speed
\end{itemize}

