\textcolor{primaryblue}{\textbf{Problem:}} Find $\vec{r}'(t)$ and $\vec{r}''(t)$ for $\vec{r}(t) = \langle t^2, e^t, \sin t \rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{First derivative:} Differentiate each component

\[
\vec{r}'(t) = \langle 2t, e^t, \cos t \rangle
\]

\textbf{Second derivative:} Differentiate $\vec{r}'(t)$

\[
\vec{r}''(t) = \langle 2, e^t, -\sin t \rangle
\]

\textbf{Answer:}
\begin{align*}
\vec{r}'(t) &= \boxed{\langle 2t, e^t, \cos t \rangle} \\
\vec{r}''(t) &= \boxed{\langle 2, e^t, -\sin t \rangle}
\end{align*}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Interpretation:}} $\vec{r}'(t)$ is velocity, $\vec{r}''(t)$ is acceleration.

\vspace{0.5cm}

Let $\vec{u}(t)$ and $\vec{v}(t)$ be differentiable vector functions, $c$ a scalar, and $f(t)$ a scalar function.

\begin{enumerate}
    \item $\dfrac{d}{dt}[c\vec{u}(t)] = c\vec{u}'(t)$

    \item $\dfrac{d}{dt}[\vec{u}(t) + \vec{v}(t)] = \vec{u}'(t) + \vec{v}'(t)$

    \item $\dfrac{d}{dt}[f(t)\vec{u}(t)] = f'(t)\vec{u}(t) + f(t)\vec{u}'(t)$ \hfill (product rule)

    \item $\dfrac{d}{dt}[\vec{u}(t) \cdot \vec{v}(t)] = \vec{u}'(t) \cdot \vec{v}(t) + \vec{u}(t) \cdot \vec{v}'(t)$ \hfill (dot product)

    \item $\dfrac{d}{dt}[\vec{u}(t) \times \vec{v}(t)] = \vec{u}'(t) \times \vec{v}(t) + \vec{u}(t) \times \vec{v}'(t)$ \hfill (cross product)

    \item $\dfrac{d}{dt}[\vec{u}(f(t))] = \vec{u}'(f(t))f'(t)$ \hfill (chain rule)
\end{enumerate}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Warning:}}

In rule 5, order matters for cross products! Don't switch the order of $\vec{u}'(t) \times \vec{v}(t)$ and $\vec{u}(t) \times \vec{v}'(t)$.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} If $\vec{r}(t) = \langle \cos t, \sin t, t \rangle$, show that $\vec{r}(t) \cdot \vec{r}'(t) = t$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find $\vec{r}'(t)$

\[
\vec{r}'(t) = \langle -\sin t, \cos t, 1 \rangle
\]

\textbf{Step 2:} Compute dot product

\begin{align*}
\vec{r}(t) \cdot \vec{r}'(t) &= \langle \cos t, \sin t, t \rangle \cdot \langle -\sin t, \cos t, 1 \rangle \\
&= (\cos t)(-\sin t) + (\sin t)(\cos t) + t(1) \\
&= -\sin t \cos t + \sin t \cos t + t \\
&= t
\end{align*}

\textbf{Answer:} $\vec{r}(t) \cdot \vec{r}'(t) = t$ \textcolor{green}{\checkmark}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Alternative using product rule:}}

\begin{align*}
\frac{d}{dt}[\vec{r}(t) \cdot \vec{r}(t)] &= 2\vec{r}(t) \cdot \vec{r}'(t) \\
\frac{d}{dt}[|\vec{r}(t)|^2] &= 2\vec{r}(t) \cdot \vec{r}'(t) \\
\frac{d}{dt}[\cos^2 t + \sin^2 t + t^2] &= 2\vec{r}(t) \cdot \vec{r}'(t) \\
2t &= 2\vec{r}(t) \cdot \vec{r}'(t) \\
t &= \vec{r}(t) \cdot \vec{r}'(t)
\end{align*}

\vspace{0.5cm}

The \textbf{unit tangent vector} to a curve at a point is:
\[
\boxed{\vec{T}(t) = \frac{\vec{r}'(t)}{|\vec{r}'(t)|}}
\]

This is a unit vector in the direction of $\vec{r}'(t)$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Properties:}}
\begin{itemize}
    \item $|\vec{T}(t)| = 1$ (unit vector)
    \item $\vec{T}(t)$ is tangent to the curve
    \item Points in direction of increasing $t$
\end{itemize}

\vspace{0.5cm}

The \textbf{indefinite integral} of $\vec{r}(t) = \langle f(t), g(t), h(t) \rangle$ is:
\[
\boxed{\int \vec{r}(t) \, dt = \left\langle \int f(t) \, dt, \int g(t) \, dt, \int h(t) \, dt \right\rangle + \vec{C}}
\]

where $\vec{C}$ is a constant vector.

The \textbf{definite integral} is:
\[
\boxed{\int_a^b \vec{r}(t) \, dt = \left\langle \int_a^b f(t) \, dt, \int_a^b g(t) \, dt, \int_a^b h(t) \, dt \right\rangle}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Key Point:}}

Integration is done component-wise, just like differentiation.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Fundamental Theorem:}}
\[
\int_a^b \vec{r}'(t) \, dt = \vec{r}(b) - \vec{r}(a)
\]

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find:

(a) $\displaystyle \int \langle 2t, \cos t, e^t \rangle \, dt$

(b) $\displaystyle \int_0^1 \langle t^2, t, 1 \rangle \, dt$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} Integrate each component:

\begin{align*}
\int \langle 2t, \cos t, e^t \rangle \, dt &= \left\langle \int 2t \, dt, \int \cos t \, dt, \int e^t \, dt \right\rangle \\
&= \langle t^2, \sin t, e^t \rangle + \vec{C}
\end{align*}

\textbf{Answer (a):} \boxed{\langle t^2, \sin t, e^t \rangle + \vec{C}}

\vspace{0.3cm}
\textbf{(b)} Integrate and evaluate:

\begin{align*}
\int_0^1 \langle t^2, t, 1 \rangle \, dt &= \left\langle \int_0^1 t^2 \, dt, \int_0^1 t \, dt, \int_0^1 1 \, dt \right\rangle \\
&= \left\langle \left[\frac{t^3}{3}\right]_0^1, \left[\frac{t^2}{2}\right]_0^1, [t]_0^1 \right\rangle \\
&= \left\langle \frac{1}{3}, \frac{1}{2}, 1 \right\rangle
\end{align*}

\textbf{Answer (b):} \boxed{\left\langle \frac{1}{3}, \frac{1}{2}, 1 \right\rangle}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find $\vec{r}(t)$ if $\vec{r}'(t) = \langle 6t, 3t^2, 2 \rangle$ and $\vec{r}(0) = \langle 1, -1, 3 \rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Integrate $\vec{r}'(t)$

\begin{align*}
\vec{r}(t) &= \int \langle 6t, 3t^2, 2 \rangle \, dt \\
&= \langle 3t^2, t^3, 2t \rangle + \vec{C}
\end{align*}

where $\vec{C} = \langle C_1, C_2, C_3 \rangle$ is a constant vector.

\textbf{Step 2:} Apply initial condition

\[
\vec{r}(0) = \langle 0, 0, 0 \rangle + \vec{C} = \langle 1, -1, 3 \rangle
\]

Therefore: $\vec{C} = \langle 1, -1, 3 \rangle$

\textbf{Step 3:} Write final answer

\[
\vec{r}(t) = \langle 3t^2, t^3, 2t \rangle + \langle 1, -1, 3 \rangle = \langle 3t^2 + 1, t^3 - 1, 2t + 3 \rangle
\]

\textbf{Answer:} \boxed{\vec{r}(t) = \langle 3t^2 + 1, t^3 - 1, 2t + 3 \rangle}

\textbf{Verification:} 
\begin{itemize}
    \item $\vec{r}'(t) = \langle 6t, 3t^2, 2 \rangle$ \textcolor{green}{\checkmark}
    \item $\vec{r}(0) = \langle 1, -1, 3 \rangle$ \textcolor{green}{\checkmark}
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 6.6 Summary: Derivatives and Integrals}}

\textbf{Derivative:}
\[
\boxed{\vec{r}'(t) = \langle f'(t), g'(t), h'(t) \rangle}
\]

\textbf{Unit Tangent Vector:}
\[
\boxed{\vec{T}(t) = \frac{\vec{r}'(t)}{|\vec{r}'(t)|}}
\]

\textbf{Indefinite Integral:}
\[
\boxed{\int \vec{r}(t) \, dt = \left\langle \int f(t) \, dt, \int g(t) \, dt, \int h(t) \, dt \right\rangle + \vec{C}}
\]

\textbf{Definite Integral:}
\[
\boxed{\int_a^b \vec{r}(t) \, dt = \left\langle \int_a^b f(t) \, dt, \int_a^b g(t) \, dt, \int_a^b h(t) \, dt \right\rangle}
\]

\textbf{Product Rules:}
\begin{align*}
\frac{d}{dt}[\vec{u} \cdot \vec{v}] &= \vec{u}' \cdot \vec{v} + \vec{u} \cdot \vec{v}' \\
\frac{d}{dt}[\vec{u} \times \vec{v}] &= \vec{u}' \times \vec{v} + \vec{u} \times \vec{v}'
\end{align*}

\textbf{Physical Interpretations:}
\begin{itemize}
    \item $\vec{r}(t)$: position
    \item $\vec{r}'(t) = \vec{v}(t)$: velocity
    \item $\vec{r}''(t) = \vec{a}(t)$: acceleration
    \item $|\vec{r}'(t)|$: speed
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Forgetting to include constant vector $\vec{C}$ in indefinite integrals
    \item Not differentiating/integrating all components
    \item Order errors in cross product differentiation
    \item Forgetting that $\vec{T}(t)$ must be a unit vector
\end{itemize}

\textcolor{green}{\textbf{Key Insight:}} Differentiation and integration of vector functions work component-wise, just like scalar functions.

