\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find an equation of the plane through $P(1, 2, 3)$ with normal vector $\vec{n} = \langle 2, -1, 4 \rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Method 1: Scalar form}

Using $a(x - x_0) + b(y - y_0) + c(z - z_0) = 0$:

\[
2(x - 1) + (-1)(y - 2) + 4(z - 3) = 0
\]

Expand:
\begin{align*}
2x - 2 - y + 2 + 4z - 12 &= 0 \\
2x - y + 4z - 12 &= 0
\end{align*}

\textbf{Method 2: General form directly}

$d = -(2 \cdot 1 + (-1) \cdot 2 + 4 \cdot 3) = -(2 - 2 + 12) = -12$

So: $2x - y + 4z - 12 = 0$

\textbf{Answer:} \boxed{2x - y + 4z = 12} or \boxed{2x - y + 4z - 12 = 0}

\textbf{Verification:} Point $(1, 2, 3)$ satisfies: $2(1) - 2 + 4(3) = 2 - 2 + 12 = 12$ \textcolor{green}{\checkmark}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find an equation of the plane through $P(1, 0, 2)$, $Q(2, 1, 1)$, and $R(0, 2, 3)$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find two vectors in the plane

\begin{align*}
\overrightarrow{PQ} &= \langle 2-1, 1-0, 1-2 \rangle = \langle 1, 1, -1 \rangle \\
\overrightarrow{PR} &= \langle 0-1, 2-0, 3-2 \rangle = \langle -1, 2, 1 \rangle
\end{align*}

\textbf{Step 2:} Find normal vector using cross product

\[
\vec{n} = \overrightarrow{PQ} \times \overrightarrow{PR} = \begin{vmatrix}
\vec{i} & \vec{j} & \vec{k} \\
1 & 1 & -1 \\
-1 & 2 & 1
\end{vmatrix}
\]

\begin{align*}
&= \vec{i}(1 + 2) - \vec{j}(1 - 1) + \vec{k}(2 + 1) \\
&= 3\vec{i} - 0\vec{j} + 3\vec{k} \\
&= \langle 3, 0, 3 \rangle
\end{align*}

\textbf{Step 3:} Use point $P(1, 0, 2)$ and normal $\vec{n} = \langle 3, 0, 3 \rangle$

\begin{align*}
3(x - 1) + 0(y - 0) + 3(z - 2) &= 0 \\
3x - 3 + 3z - 6 &= 0 \\
3x + 3z &= 9 \\
x + z &= 3
\end{align*}

\textbf{Answer:} \boxed{x + z = 3}

\textbf{Verification:} Check that all three points satisfy the equation:
\begin{itemize}
    \item $P(1, 0, 2)$: $1 + 2 = 3$ \textcolor{green}{\checkmark}
    \item $Q(2, 1, 1)$: $2 + 1 = 3$ \textcolor{green}{\checkmark}
    \item $R(0, 2, 3)$: $0 + 3 = 3$ \textcolor{green}{\checkmark}
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Determine if the planes are parallel, perpendicular, or neither:

(a) $2x - y + 3z = 5$ and $4x - 2y + 6z = 1$

(b) $x + 2y - z = 3$ and $2x - y + 2z = 7$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} Identify normal vectors:

\begin{align*}
\vec{n}_1 &= \langle 2, -1, 3 \rangle \\
\vec{n}_2 &= \langle 4, -2, 6 \rangle
\end{align*}

Check if one is a multiple of the other:
\[
\vec{n}_2 = 2\vec{n}_1 = 2\langle 2, -1, 3 \rangle = \langle 4, -2, 6 \rangle \quad \checkmark
\]

\textbf{Answer (a):} \boxed{\text{Parallel}}

\vspace{0.3cm}
\textbf{(b)} Identify normal vectors:

\begin{align*}
\vec{n}_1 &= \langle 1, 2, -1 \rangle \\
\vec{n}_2 &= \langle 2, -1, 2 \rangle
\end{align*}

Check dot product:
\[
\vec{n}_1 \cdot \vec{n}_2 = (1)(2) + (2)(-1) + (-1)(2) = 2 - 2 - 2 = -2 \neq 0
\]

Not perpendicular. Check if parallel:
\[
\vec{n}_2 \neq k\vec{n}_1 \text{ for any scalar } k
\]

\textbf{Answer (b):} \boxed{\text{Neither parallel nor perpendicular}}

\vspace{0.5cm}

To find where a line intersects a plane:

\textbf{Method:}
\begin{enumerate}
    \item Write line in parametric form: $x = x_0 + at$, $y = y_0 + bt$, $z = z_0 + ct$
    \item Substitute into plane equation $Ax + By + Cz + D = 0$
    \item Solve for parameter $t$
    \item Substitute $t$ back into parametric equations
\end{enumerate}

\textbf{Special Cases:}
\begin{itemize}
    \item If solution for $t$ exists: line intersects plane at one point
    \item If $0 = 0$ (identity): line lies in the plane
    \item If $0 = k$ (contradiction): line is parallel to plane, no intersection
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the point where the line $x = 1 + 2t$, $y = -1 + t$, $z = 3 - t$ intersects the plane $x + y + z = 5$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Substitute parametric equations into plane equation

\[
(1 + 2t) + (-1 + t) + (3 - t) = 5
\]

\textbf{Step 2:} Solve for $t$

\begin{align*}
1 + 2t - 1 + t + 3 - t &= 5 \\
2t + 3 &= 5 \\
2t &= 2 \\
t &= 1
\end{align*}

\textbf{Step 3:} Find intersection point by substituting $t = 1$

\begin{align*}
x &= 1 + 2(1) = 3 \\
y &= -1 + 1 = 0 \\
z &= 3 - 1 = 2
\end{align*}

\textbf{Answer:} \boxed{(3, 0, 2)}

\textbf{Verification:} $3 + 0 + 2 = 5$ \textcolor{green}{\checkmark}

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 6.8 Summary: Planes in $\mathbb{R}^3$}}

\textbf{Equation of a Plane:}
\[
\boxed{a(x - x_0) + b(y - y_0) + c(z - z_0) = 0}
\]

or in general form:
\[
\boxed{ax + by + cz + d = 0}
\]

where $\vec{n} = \langle a, b, c \rangle$ is the normal vector.

\textbf{Plane Through Three Points:}
\begin{enumerate}
    \item Find two vectors in the plane: $\overrightarrow{PQ}$ and $\overrightarrow{PR}$
    \item Normal vector: $\vec{n} = \overrightarrow{PQ} \times \overrightarrow{PR}$
    \item Use any of the three points with the normal vector
\end{enumerate}

\textbf{Parallel Planes:} $\vec{n}_1 = k\vec{n}_2$

\textbf{Perpendicular Planes:} $\vec{n}_1 \cdot \vec{n}_2 = 0$

\textbf{Line-Plane Intersection:}
\begin{itemize}
    \item Substitute line's parametric equations into plane equation
    \item Solve for parameter $t$
    \item Substitute back to find point
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Using a direction vector instead of normal vector for plane
    \item Sign errors when expanding plane equation
    \item Not verifying that computed points satisfy the equation
    \item Confusing parallel lines with parallel planes (different tests!)
\end{itemize}

\textcolor{green}{\textbf{Key Insight:}} The normal vector is perpendicular to the plane, while direction vectors lie in the plane. For lines, we use direction vectors; for planes, we use normal vectors.

