\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Convert the spherical coordinates $(6, \frac{\pi}{4}, \frac{\pi}{3})$ to Cartesian coordinates.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

Given: $\rho = 6$, $\theta = \frac{\pi}{4}$, $\phi = \frac{\pi}{3}$

\textbf{Apply conversion formulas:}

\begin{align*}
x &= \rho\sin\phi\cos\theta = 6\sin\frac{\pi}{3}\cos\frac{\pi}{4} \\
&= 6 \cdot \frac{\sqrt{3}}{2} \cdot \frac{\sqrt{2}}{2} = \frac{6\sqrt{6}}{4} = \frac{3\sqrt{6}}{2}
\end{align*}

\begin{align*}
y &= \rho\sin\phi\sin\theta = 6\sin\frac{\pi}{3}\sin\frac{\pi}{4} \\
&= 6 \cdot \frac{\sqrt{3}}{2} \cdot \frac{\sqrt{2}}{2} = \frac{3\sqrt{6}}{2}
\end{align*}

\begin{align*}
z &= \rho\cos\phi = 6\cos\frac{\pi}{3} = 6 \cdot \frac{1}{2} = 3
\end{align*}

\textbf{Answer:} \boxed{\left(\frac{3\sqrt{6}}{2}, \frac{3\sqrt{6}}{2}, 3\right)}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Describe the surfaces given by these equations:

(a) Cylindrical: $r = 3$

(b) Cylindrical: $\theta = \frac{\pi}{6}$

(c) Spherical: $\rho = 5$

(d) Spherical: $\phi = \frac{\pi}{4}$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} $r = 3$ in cylindrical coordinates

This means the distance from the $z$-axis is constant (3 units).

\textbf{Answer (a):} \boxed{\text{Circular cylinder of radius 3 about the } z\text{-axis}}

\vspace{0.3cm}
\textbf{(b)} $\theta = \frac{\pi}{6}$ in cylindrical coordinates

The angle in the $xy$-plane is constant.

\textbf{Answer (b):} \boxed{\text{Half-plane through the } z\text{-axis at angle } \frac{\pi}{6}}

\vspace{0.3cm}
\textbf{(c)} $\rho = 5$ in spherical coordinates

Distance from origin is constant (5 units).

\textbf{Answer (c):} \boxed{\text{Sphere of radius 5 centered at the origin}}

\vspace{0.3cm}
\textbf{(d)} $\phi = \frac{\pi}{4}$ in spherical coordinates

Angle from positive $z$-axis is constant ($45°$).

\textbf{Answer (d):} \boxed{\text{Cone with vertex at origin, opening angle } 45°}

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 6.9 Summary: Coordinate Systems}}

\textbf{Cylindrical $(r, \theta, z)$:}
\[
\boxed{\begin{cases}
x = r\cos\theta \\
y = r\sin\theta \\
z = z
\end{cases}} \qquad
\boxed{\begin{cases}
r = \sqrt{x^2 + y^2} \\
\theta = \arctan(y/x) \\
z = z
\end{cases}}
\]

\textbf{Spherical $(\rho, \theta, \phi)$:}
\[
\boxed{\begin{cases}
x = \rho\sin\phi\cos\theta \\
y = \rho\sin\phi\sin\theta \\
z = \rho\cos\phi
\end{cases}} \qquad
\boxed{\begin{cases}
\rho = \sqrt{x^2 + y^2 + z^2} \\
\theta = \arctan(y/x) \\
\phi = \arccos(z/\rho)
\end{cases}}
\]

\textbf{Common Surfaces:}
\begin{center}
\begin{tabular}{|p{3cm}|p{4.5cm}|p{4.5cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Surface} & \textbf{Cylindrical} & \textbf{Spherical} \\
\hline
Cylinder & $r = a$ & $\rho\sin\phi = a$ \\
\hline
Sphere & $r^2 + z^2 = a^2$ & $\rho = a$ \\
\hline
Cone & $z = kr$ & $\phi = \text{const}$ \\
\hline
Plane $z = c$ & $z = c$ & $\rho\cos\phi = c$ \\
\hline
\end{tabular}
\end{center}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Confusing $r$ (cylindrical) with $\rho$ (spherical)
    \item Wrong quadrant for $\theta$ when converting from Cartesian
    \item Using degrees instead of radians
    \item Confusing angle conventions (check which is used!)
\end{itemize}

\newpage

If a smooth curve $C$ is given by $\vec{r}(t) = \langle f(t), g(t), h(t) \rangle$ for $a \leq t \leq b$, then the \textbf{arc length} of $C$ is:
\[
\boxed{L = \int_a^b |\vec{r}'(t)| \, dt = \int_a^b \sqrt{[f'(t)]^2 + [g'(t)]^2 + [h'(t)]^2} \, dt}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Interpretation:}}

Arc length measures the actual distance traveled along the curve from $t = a$ to $t = b$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Speed:}}

The speed at time $t$ is $|\vec{r}'(t)|$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Arc Length Function:}}

The arc length from $t = a$ to $t = s$ is:
\[
s(t) = \int_a^t |\vec{r}'(u)| \, du
\]

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the length of the curve $\vec{r}(t) = \langle 2t, t^2, \frac{1}{3}t^3 \rangle$ from $t = 0$ to $t = 3$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find $\vec{r}'(t)$

\[
\vec{r}'(t) = \langle 2, 2t, t^2 \rangle
\]

\textbf{Step 2:} Find $|\vec{r}'(t)|$

\begin{align*}
|\vec{r}'(t)| &= \sqrt{2^2 + (2t)^2 + (t^2)^2} \\
&= \sqrt{4 + 4t^2 + t^4} \\
&= \sqrt{(t^2 + 2)^2} \\
&= t^2 + 2
\end{align*}

\textbf{Step 3:} Integrate

\begin{align*}
L &= \int_0^3 (t^2 + 2) \, dt \\
&= \left[\frac{t^3}{3} + 2t\right]_0^3 \\
&= \frac{27}{3} + 6 - 0 \\
&= 9 + 6 \\
&= 15
\end{align*}

\textbf{Answer:} \boxed{L = 15 \text{ units}}

\vspace{0.5cm}

The \textbf{curvature} $\kappa$ of a curve at a point measures how sharply the curve bends at that point.

\textbf{Formula 1 (using arc length parameter):}
\[
\boxed{\kappa = \left|\frac{d\vec{T}}{ds}\right|}
\]

where $\vec{T}$ is the unit tangent vector and $s$ is arc length.

\textbf{Formula 2 (using parameter $t$):}
\[
\boxed{\kappa(t) = \frac{|\vec{T}'(t)|}{|\vec{r}'(t)|}}
\]

\textbf{Formula 3 (practical formula):}
\[
\boxed{\kappa(t) = \frac{|\vec{r}'(t) \times \vec{r}''(t)|}{|\vec{r}'(t)|^3}}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Interpretation:}}
\begin{itemize}
    \item $\kappa = 0$: curve is a straight line at that point
    \item Large $\kappa$: curve bends sharply
    \item Small $\kappa$: curve bends gently
\end{itemize}

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Radius of Curvature:}}
\[
\rho = \frac{1}{\kappa}
\]

This is the radius of the "best-fit" circle at that point.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the curvature of the helix $\vec{r}(t) = \langle \cos t, \sin t, t \rangle$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find $\vec{r}'(t)$ and $\vec{r}''(t)$

\begin{align*}
\vec{r}'(t) &= \langle -\sin t, \cos t, 1 \rangle \\
\vec{r}''(t) &= \langle -\cos t, -\sin t, 0 \rangle
\end{align*}

\textbf{Step 2:} Compute cross product $\vec{r}'(t) \times \vec{r}''(t)$

\[
\vec{r}'(t) \times \vec{r}''(t) = \begin{vmatrix}
\vec{i} & \vec{j} & \vec{k} \\
-\sin t & \cos t & 1 \\
-\cos t & -\sin t & 0
\end{vmatrix}
\]

\begin{align*}
&= \vec{i}(0 + \sin t) - \vec{j}(0 + \cos t) + \vec{k}(\sin^2 t + \cos^2 t) \\
&= \langle \sin t, -\cos t, 1 \rangle
\end{align*}

\textbf{Step 3:} Find magnitudes

\begin{align*}
|\vec{r}'(t) \times \vec{r}''(t)| &= \sqrt{\sin^2 t + \cos^2 t + 1} = \sqrt{2} \\
|\vec{r}'(t)| &= \sqrt{\sin^2 t + \cos^2 t + 1} = \sqrt{2}
\end{align*}

\textbf{Step 4:} Apply curvature formula

\[
\kappa(t) = \frac{|\vec{r}'(t) \times \vec{r}''(t)|}{|\vec{r}'(t)|^3} = \frac{\sqrt{2}}{(\sqrt{2})^3} = \frac{\sqrt{2}}{2\sqrt{2}} = \frac{1}{2}
\]

\textbf{Answer:} \boxed{\kappa = \frac{1}{2}} (constant curvature)

\textcolor{primaryblue}{\faLightbulb\ \textbf{Interpretation:}} The helix has constant curvature $\frac{1}{2}$ at every point.

\vspace{0.5cm}

\textbf{1. Circular Helix:}
\[
\vec{r}(t) = \langle a\cos t, a\sin t, bt \rangle
\]
Properties:
\begin{itemize}
    \item Projects to circle of radius $a$ in $xy$-plane
    \item Rises at constant rate $b$ (pitch)
    \item Constant curvature: $\kappa = \frac{a}{a^2 + b^2}$
\end{itemize}

\textbf{2. Twisted Cubic (Space Curve):}
\[
\vec{r}(t) = \langle t, t^2, t^3 \rangle
\]

\textbf{3. Astroid (when projected to a plane):}

In the $xy$-plane:
\[
\vec{r}(t) = \langle a\cos^3 t, a\sin^3 t \rangle
\]

This is a star-shaped curve with four cusps.

\textbf{Arc length of astroid:}
\[
L = 6a \quad \text{(one complete loop)}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Properties:}}

The astroid is the path traced by a point on a small circle rolling inside a larger circle (with radius ratio 4:1).

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the arc length of one loop of the astroid $\vec{r}(t) = \langle \cos^3 t, \sin^3 t \rangle$ for $0 \leq t \leq 2\pi$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find $\vec{r}'(t)$

\begin{align*}
\vec{r}'(t) &= \langle -3\cos^2 t \sin t, 3\sin^2 t \cos t \rangle
\end{align*}

\textbf{Step 2:} Find $|\vec{r}'(t)|$

\begin{align*}
|\vec{r}'(t)| &= \sqrt{9\cos^4 t \sin^2 t + 9\sin^4 t \cos^2 t} \\
&= 3\sqrt{\cos^4 t \sin^2 t + \sin^4 t \cos^2 t} \\
&= 3\sqrt{\cos^2 t \sin^2 t(\cos^2 t + \sin^2 t)} \\
&= 3|\cos t \sin t| \\
&= 3|\sin t \cos t|
\end{align*}

\textbf{Step 3:} Set up integral (using symmetry)

Due to symmetry, we can compute for one quarter $(0 \to \frac{\pi}{2})$ and multiply by 4:

\begin{align*}
L &= 4\int_0^{\pi/2} 3\sin t \cos t \, dt \\
&= 12\int_0^{\pi/2} \sin t \cos t \, dt \\
&= 12 \cdot \frac{1}{2}\int_0^{\pi/2} \sin(2t) \, dt \\
&= 6\left[-\frac{1}{2}\cos(2t)\right]_0^{\pi/2} \\
&= 6 \cdot \frac{1}{2}[1 - (-1)] \\
&= 3 \cdot 2 \\
&= 6
\end{align*}

\textbf{Answer:} \boxed{L = 6 \text{ units}} (for $a = 1$)

\textcolor{primaryblue}{\faLightbulb\ \textbf{General:}} For astroid with parameter $a$: $L = 6a$

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 6.10 Summary: Curves in Space}}

\textbf{Arc Length:}
\[
\boxed{L = \int_a^b |\vec{r}'(t)| \, dt}
\]

\textbf{Curvature:}
\[
\boxed{\kappa(t) = \frac{|\vec{r}'(t) \times \vec{r}''(t)|}{|\vec{r}'(t)|^3}}
\]

\textbf{Key Formulas:}
\begin{itemize}
    \item Speed: $|\vec{r}'(t)|$
    \item Unit tangent: $\vec{T}(t) = \frac{\vec{r}'(t)}{|\vec{r}'(t)|}$
    \item Radius of curvature: $\rho = \frac{1}{\kappa}$
\end{itemize}

\textbf{Special Curves:}
\begin{itemize}
    \item Helix: $\vec{r}(t) = \langle a\cos t, a\sin t, bt \rangle$ (constant curvature)
    \item Astroid: $\vec{r}(t) = \langle a\cos^3 t, a\sin^3 t \rangle$ (arc length $6a$)
    \item Twisted cubic: $\vec{r}(t) = \langle t, t^2, t^3 \rangle$
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Forgetting to take magnitude of $\vec{r}'(t)$ in arc length
    \item Sign errors in cross product for curvature
    \item Not using symmetry to simplify arc length integrals
    \item Confusing curvature with radius of curvature
\end{itemize}

\textcolor{green}{\textbf{Key Insight:}} Curvature measures how sharply a curve bends; arc length measures total distance along the curve.

